import struct, zlib
for f in ['image1.png','image2.png']:
    d=open('/workspace/'+f,'rb').read()
    i=8
    while i<len(d):
        L,=struct.unpack('>I',d[i:i+4]); t=d[i+4:i+8]; c=d[i+8:i+8+L]
        if t==b'iCCP':
            z=c.index(0)+2
            try:
                p=zlib.decompress(c[z:]); print(f,'iCCP',len(p)); print(p[:120])
            except Exception as e: print('iCCP err',e)
        if t==b'eXIf': print(f,'eXIf',c)
        i+=12+L

